#include <iostream>
#include <print>
#include <set>
#include <stdexcept>
#include <string>

class AppError : public std::runtime_error {
public:
    using std::runtime_error::runtime_error;

    virtual int code() const {
        return 500;
    }
};

class NotFound : public AppError {
public:
    explicit NotFound(int n) : AppError("нет записи " + std::to_string(n)) {}

    int code() const override {
        return 404;
    }
};

class Denied : public AppError {
public:
    explicit Denied(const std::string &user) : AppError("нет прав у " + user) {}

    int code() const override {
        return 403;
    }
};

class Storage {
public:
    Storage() {
        for (int i = 1; i <= 10; i++) {
            records_.insert(i);
        }
    }

    void get(int n) const {
        if (!records_.contains(n)) {
            throw NotFound(n);
        }
        std::println("запись {}", n);
    }

    void remove(int n, const std::string &user) {
        if (user != "admin") {
            throw Denied(user);
        }
        if (records_.erase(n) == 0) {
            throw NotFound(n);
        }
        std::println("удалена {}", n);
    }

private:
    std::set<int> records_;
};

int main() {
    Storage storage;
    std::string command;
    while (std::cin >> command) {
        int n;
        std::cin >> n;
        std::string user;
        if (command == "delete") {
            std::cin >> user;
        }
        try {
            if (command == "get") {
                storage.get(n);
            } else {
                storage.remove(n, user);
            }
        } catch (const AppError &e) {
            std::println("[{}] {}", e.code(), e.what());
        }
    }
    return 0;
}

